// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;

    function setUp() public {
        c = new Synth(address(this), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(uint256 initialAllowance, uint256 subtractedValue) public {
        address spender = address(0xBEEF);
        subtractedValue = bound(subtractedValue, 0, initialAllowance);

        c.approve(spender, initialAllowance);
        assertEq(c.allowance(address(this), spender), initialAllowance);

        bool ok = c.decreaseAllowance(spender, subtractedValue);
        assertTrue(ok);
        assertTrue(c.allowance(address(this), spender) == initialAllowance - subtractedValue);
    }
}

